//
// A register file generated by airhdl, driven by the JSON register map that
// jig.ext.airhdl extracts from the RTL packages, so the simulated PL
// always matches the RTL revision in the repository.
//
// Per register access kind (from the airhdl module ports):
//  - rw: software writes and reads back the stored value (fields keep their
//    airhdl reset values).
//  - ro: hardware drives the value; the owning model supplies it through
//    SetHardware or a provider callback. Writes are ignored.
//  - w1c fields (hardware "set" pulses): RaiseEvent sets them, software clears
//    them by writing 1.
//  - memories without a read port are write-only: writes are stored (and
//    reported), reads return 0, as the airhdl bus slave returns.
// Offsets that belong to no register read 0 and ignore writes, with a warning.
//
using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using Antmicro.Renode.Exceptions;

namespace Antmicro.Renode.Peripherals.Jig.Harness
{
    public sealed class AirhdlRegisterBlock
    {
        public AirhdlRegisterBlock(string jsonPath)
        {
            if(string.IsNullOrEmpty(jsonPath) || !File.Exists(jsonPath))
            {
                throw new RecoverableException($"airhdl register map not found: {jsonPath}");
            }
            using(var document = JsonDocument.Parse(File.ReadAllText(jsonPath)))
            {
                var root = document.RootElement;
                Name = root.GetProperty("name").GetString();
                foreach(var element in root.GetProperty("registers").EnumerateArray())
                {
                    var register = new Register
                    {
                        Name = element.GetProperty("name").GetString(),
                        Offset = element.GetProperty("offset").GetInt64(),
                        Access = element.GetProperty("access").GetString(),
                        Reset = (uint)element.GetProperty("reset").GetInt64(),
                    };
                    foreach(var field in element.GetProperty("fields").EnumerateArray())
                    {
                        if(field.GetProperty("kind").GetString() == "w1c")
                        {
                            var offset = field.GetProperty("offset").GetInt32();
                            var width = field.GetProperty("width").GetInt32();
                            register.EventMask |= (uint)(((1UL << width) - 1) << offset);
                            register.EventFields[field.GetProperty("name").GetString().ToLowerInvariant()] = (offset, width);
                        }
                    }
                    byOffset[register.Offset] = register;
                    byName[register.Name.ToLowerInvariant()] = register;
                }
                foreach(var element in root.GetProperty("memories").EnumerateArray())
                {
                    var memory = new Memory
                    {
                        Name = element.GetProperty("name").GetString(),
                        Offset = element.GetProperty("offset").GetInt64(),
                        Depth = element.GetProperty("depth").GetInt32(),
                        Readable = element.GetProperty("readable").GetBoolean(),
                    };
                    memory.Words = new uint[memory.Depth];
                    memories.Add(memory);
                    byName[memory.Name.ToLowerInvariant()] = null;
                    memoryByName[memory.Name.ToLowerInvariant()] = memory;
                }
            }
            Reset();
        }

        public string Name { get; }

        /// <summary>Raised after software writes a register (name, value written).</summary>
        public event Action<string, uint> RegisterWritten;

        /// <summary>Raised after software writes a memory word (memory, index, value).</summary>
        public event Action<string, int, uint> MemoryWritten;

        /// <summary>Reports accesses to offsets no register covers.</summary>
        public event Action<string> Diagnostic;

        public void Reset()
        {
            foreach(var register in byOffset.Values)
            {
                register.Value = register.Reset;
            }
            foreach(var memory in memories)
            {
                Array.Clear(memory.Words, 0, memory.Words.Length);
            }
        }

        public uint Read(long offset)
        {
            if(byOffset.TryGetValue(offset, out var register))
            {
                if(register.Access == "ro" && register.Provider != null)
                {
                    return register.Provider();
                }
                return register.Value;
            }
            if(TryFindMemory(offset, out var memory, out var index))
            {
                return memory.Readable ? memory.Words[index] : 0;
            }
            Diagnostic?.Invoke($"{Name}: read from unmapped offset 0x{offset:X3}");
            return 0;
        }

        public void Write(long offset, uint value)
        {
            if(byOffset.TryGetValue(offset, out var register))
            {
                if(register.Access == "ro")
                {
                    Diagnostic?.Invoke($"{Name}: write 0x{value:X8} to read-only {register.Name} ignored");
                    return;
                }
                var cleared = register.Value & register.EventMask & value;
                var stored = (value & ~register.EventMask) | (register.Value & register.EventMask & ~cleared);
                register.Value = stored;
                RegisterWritten?.Invoke(register.Name, value);
                return;
            }
            if(TryFindMemory(offset, out var memory, out var index))
            {
                memory.Words[index] = value;
                MemoryWritten?.Invoke(memory.Name, index, value);
                return;
            }
            Diagnostic?.Invoke($"{Name}: write 0x{value:X8} to unmapped offset 0x{offset:X3} ignored");
        }

        public uint GetValue(string registerName) => Find(registerName).Value;

        public long OffsetOf(string registerName) => Find(registerName).Offset;

        public void SetHardware(string registerName, uint value)
        {
            var register = Find(registerName);
            register.Value = value;
        }

        public void SetProvider(string registerName, Func<uint> provider)
        {
            var register = Find(registerName);
            if(register.Access != "ro")
            {
                throw new RecoverableException($"{Name}.{register.Name} is software-written; only read-only registers take a provider");
            }
            register.Provider = provider;
        }

        public void RaiseEvent(string registerName, string fieldName)
        {
            var register = Find(registerName);
            if(!register.EventFields.TryGetValue(fieldName.ToLowerInvariant(), out var position))
            {
                throw new RecoverableException($"{Name}.{register.Name} has no hardware-set field '{fieldName}'");
            }
            register.Value |= (uint)(((1UL << position.Width) - 1) << position.Offset);
        }

        public uint[] GetMemory(string memoryName)
        {
            if(!memoryByName.TryGetValue(memoryName.ToLowerInvariant(), out var memory))
            {
                throw new RecoverableException($"{Name} has no memory '{memoryName}'");
            }
            return (uint[])memory.Words.Clone();
        }

        private Register Find(string registerName)
        {
            if(!byName.TryGetValue(registerName.ToLowerInvariant(), out var register) || register == null)
            {
                throw new RecoverableException($"{Name} has no register '{registerName}'");
            }
            return register;
        }

        private bool TryFindMemory(long offset, out Memory memory, out int index)
        {
            foreach(var candidate in memories)
            {
                if(offset >= candidate.Offset && offset < candidate.Offset + 4L * candidate.Depth)
                {
                    memory = candidate;
                    index = (int)((offset - candidate.Offset) / 4);
                    return true;
                }
            }
            memory = null;
            index = 0;
            return false;
        }

        private readonly Dictionary<long, Register> byOffset = new Dictionary<long, Register>();
        private readonly Dictionary<string, Register> byName = new Dictionary<string, Register>();
        private readonly Dictionary<string, Memory> memoryByName = new Dictionary<string, Memory>();
        private readonly List<Memory> memories = new List<Memory>();

        private sealed class Register
        {
            public string Name;
            public long Offset;
            public string Access;
            public uint Reset;
            public uint Value;
            public uint EventMask;
            public Func<uint> Provider;
            public readonly Dictionary<string, (int Offset, int Width)> EventFields = new Dictionary<string, (int, int)>();
        }

        private sealed class Memory
        {
            public string Name;
            public long Offset;
            public int Depth;
            public bool Readable;
            public uint[] Words;
        }
    }
}
